// Breathing Meditation Glow
// A soft, breathing glow that follows a slow vertical wave across the cylindrical helix.
// Uses fixed-point phases for performance and a subtle colour shift from base to accent.
//
// Uniforms:
//   float rate    : breathing speed (Hz) 0.0..2.0, default 0.05
//   float depth   : vertical wave depth (m) 0.0..0.5, default 0.15
//   vec3  base    : base colour (RGB) default 0.2, 0.4, 0.8
//   vec3  accent  : accent colour (RGB) default 0.9, 0.9, 1.0
//
// State:
//   state fixed ph1;   // breathing phase (turns)
//   state fixed ph2;   // vertical wave phase (turns)
//
// update() advances both phases using dt and the rate uniform, keeping them bounded with fract.
// shade() computes a per-LED glow based on the LED's vertical position (led.pos.y)
// and a breathing amplitude that oscillates over time. The vertical wave is a sin along
// the helix length (led.s) modulated by depth, and the breathing glow is a smoothstep
// around a centre that moves up and down with a slow sinusoid. All per-LED math is in
// fixed-point for speed, and the final colour is blended between base and accent.
//
// The effect is designed to stay comfortably under the 33 ms frame budget on the ESP32-C6,
// using integer LUTs for sin/cos and avoiding expensive float ops.

uniform float rate : 0.0 .. 2.0 = 0.05;
uniform float depth : 0.0 .. 0.5 = 0.15;
uniform vec3 base : color = 0.2, 0.4, 0.8;
uniform vec3 accent : color = 0.9, 0.9, 1.0;

state fixed ph1; // breathing phase
